              onClick={() => setProductFilter("minimal")}
            >
              Minimal processing
            </ControlChip>
            <ControlChip
              active={productFilter === "moderate"}
              onClick={() => setProductFilter("moderate")}
            >
              Moderate
            </ControlChip>
            <ControlChip
              active={productFilter === "heavy"}
