                    nameKey="use"
                    cx="50%"
                    cy="50%"
                    outerRadius={110}
                    label={({ sharePct }: { sharePct: number }) =>
                      `${sharePct}%`
                    }
                  >
                    {CRUSHED_USE_MIX.map((_, i) => (
                      <Cell
                        key={CRUSHED_USE_MIX[i].use}
                        fill={COLORS.pie[i % COLORS.pie.length]}
                      />
                    ))}
                  </Pie>
                  <Tooltip />
                  <Legend />
                </PieChart>
              </ResponsiveContainer>
            </div>
            <ul className="space-y-3 self-center text-sm text-slate-700">
              {CRUSHED_USE_MIX.map((u) => (
                <li
                  key={u.use}
                  className="rounded-lg border border-slate-100 bg-slate-50 px-3 py-2"
                >
                  <span className="font-semibold text-slate-900">
                    {u.sharePct}% ??? {u.use}
                  </span>
                  <p className="mt-0.5 text-slate-500">{u.note}</p>
                </li>
              ))}
            </ul>
          </div>
        </ChartCard>
      ) : null}

      {panel === "unit-scatter" ? (
        <ChartCard
          title="Unit value vs intensity"
          subtitle="As quarry prices rose, Mt per real CIP dollar fell ??? dollars and tons diverged"
        >
          <div className="h-[380px] w-full">
            <ResponsiveContainer width="100%" height="100%">
              <ScatterChart
                margin={{ top: 12, right: 12, bottom: 20, left: 12 }}
              >
                <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                <XAxis
                  type="number"
                  dataKey="crushedPrice"
                  name="Crushed $/t"
                  unit="$"
                  domain={[12, 19]}
                  tick={{ fill: "#64748b", fontSize: 12 }}
                />
                <YAxis
                  type="number"
                  dataKey="intensity"
                  name="Intensity"
                  domain={[1.4, 1.8]}
                  tick={{ fill: "#64748b", fontSize: 12 }}
                />
                <ZAxis type="number" dataKey="crushedMt" range={[80, 280]} />
                <Tooltip
                  cursor={{ strokeDasharray: "3 3" }}
                  formatter={(value: number | string, name: string) => [
                    typeof value === "number" ? value.toFixed(2) : value,
                    name,
                  ]}
                  labelFormatter={(_, payload) => {
                    const year = payload?.[0]?.payload?.year;
                    return year ? `Year ${year}` : "";
                  }}
                />
                <Scatter
                  name="Year (bubble = crushed Mt)"
                  data={scatterData}
                  fill={COLORS.crushed}
                />
              </ScatterChart>
            </ResponsiveContainer>
          </div>
        </ChartCard>
      ) : null}

      <p className="text-xs leading-relaxed text-slate-500">{SOURCE_NOTE}</p>
      <p className="text-xs text-slate-500">{ANALYTICS.story}</p>
    </div>
  );
}

