"use client";

import { useMemo, useState } from "react";
import {
  Area,
  Bar,
  BarChart,
  CartesianGrid,
  Cell,
  ComposedChart,
  Legend,
  Line,
  Pie,
  PieChart,
  PolarAngleAxis,
  PolarGrid,
  PolarRadiusAxis,
  Radar,
  RadarChart,
  ResponsiveContainer,
  Scatter,
  ScatterChart,
  Tooltip,
  XAxis,
  YAxis,
  ZAxis,
} from "recharts";
import {
  ANALYTICS,
  ANNUAL_PANEL,
  CRUSHED_USE_MIX,
  DIVISION_CRUSHED_2024,
  HEADLINE,
  INDEX_GAP,
  INTENSITY_PATH,
  SOURCE_NOTE,
  UNIT_VALUES,
} from "@/data/us-crushed-stone-vs-construction-put-in-place-2026-data";

type Panel =
  | "dual-index"
  | "intensity"
  | "division"
  | "use-mix"
  | "unit-scatter";

type IndexMode = "real" | "nominal" | "both";
type RegionFilter = "all" | "Northeast" | "Midwest" | "South" | "West";
type CommodityFocus = "total" | "crushed" | "sand";

const C = {
  crushed: "#b45309",
  sand: "#0f766e",
  aggregates: "#1e3a5f",
  realCip: "#2563eb",
  nominalCip: "#94a3b8",
  intensity: "#dc2626",
  gap: "#7c3aed",
  pie: ["#b45309", "#1e3a5f", "#0f766e", "#64748b", "#d97706"],
};

function ChartCard({
  title,
  subtitle,
  children,
}: {
  title: string;
  subtitle?: string;
  children: React.ReactNode;
}) {
  return (
    <div className="w-full min-w-0 overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm">
      <div className="border-b border-slate-100 bg-slate-50 px-5 py-4">
        <h3 className="text-lg font-bold text-slate-900">{title}</h3>
        {subtitle ? (
          <p className="mt-1 text-sm text-slate-500">{subtitle}</p>
        ) : null}
      </div>
      <div className="p-4 sm:p-6">{children}</div>
    </div>
  );
}

function Chip({
  active,
  onClick,
  children,
}: {
  active: boolean;
  onClick: () => void;
  children: React.ReactNode;
}) {
  return (
    <button
      type="button"
      onClick={onClick}
      className={`rounded-lg px-3 py-1.5 text-sm font-medium transition-colors ${
        active
          ? "bg-slate-900 text-white"
          : "bg-slate-100 text-slate-700 hover:bg-slate-200"
      }`}
    >
      {children}
    </button>
  );
}

