          <div className="grid gap-4 lg:grid-cols-2">
            <div className="h-[320px] w-full">
              <ResponsiveContainer width="100%" height="100%">
                <PieChart>
                  <Pie
                    data={CRUSHED_USE_MIX}
                    dataKey="sharePct"
                    nameKey="use"
