                    const year = payload?.[0]?.payload?.year;
                    return year ? `Year ${year}` : "";
                  }}
                />
                <Scatter
                  name="Year (bubble = crushed Mt)"
                  data={scatterData}
                  fill={C.crushed}
                />
              </ScatterChart>
            </ResponsiveContainer>
          </div>
        </ChartCard>
      ) : null}

      <p className="text-xs leading-relaxed text-slate-500">{SOURCE_NOTE}</p>
      <p className="text-xs text-slate-500">{ANALYTICS.story}</p>
    </div>
  );
}

