async function smokePost(page, { slug, marker, forbidden }) {
  const path = live ? `/blog/${slug}` : `/blog/${slug}.html`;
  const url = `${baseUrl}${path}`;
  const consoleErrors = [];
  const pageErrors = [];

  page.removeAllListeners("console");
  page.removeAllListeners("pageerror");
  page.on("console", (msg) => {
    if (msg.type() === "error") consoleErrors.push(msg.text());
  });
  page.on("pageerror", (err) => pageErrors.push(String(err)));

  await page.goto(url, { waitUntil: "networkidle", timeout: 45000 });
  await page.getByText(marker, { exact: false }).first().waitFor({ timeout: 25000 });

  const stuck = await page.getByText(forbidden, { exact: false }).isVisible().catch(() => false);

  const relevantConsole = consoleErrors.filter(
    (e) =>
      !e.includes("404") &&
      !e.includes("Failed to load resource") &&
      !e.includes("metamask") &&
      !e.includes("ObjectMultiplex"),
  );

  return { slug, url, stuck, pageErrors, consoleErrors: relevantConsole };
}

async function main() {
  if (!live) {
    const outDir = path.join(root, "out");
    if (!fs.existsSync(outDir)) {
      console.error("?????? Missing out/ ?????? run npm run build first");
      process.exit(1);
    }
  }

  let server;
  if (!live) {
    const port = Number(process.env.SMOKE_PORT || 4173);
    server = await startStaticServer(path.join(root, "out"), port);
  }

if (args.worktree) patch.worktreePath = args.worktree;
if (args.branch) patch.branch = args.branch;

// Central soft-requeue: even old worker shells that only know "--status failed
// --error transport_kill" get requeued here (budget permitting).
let softRequeued = false;
if (args.status === "failed" && !args["requeue-transport"]) {
  const err = String(args.error || existing?.lastError || "failed");
  if (isSoftRequeueError(err) && existing && !existing.recovery) {
    const preview = {
      ...existing,
      transportRequeues: existing.transportRequeues,
      recovery: existing.recovery,
    };
    if (maybeSoftRequeueTransportKill(preview, err)) {
      softRequeued = true;
      Object.assign(patch, {
        status: preview.status,
        workerId: null,
        lastError: null,
        flagged: false,
        flagReason: null,
        flaggedAt: null,
        transportRequeues: preview.transportRequeues,
        activity: preview.activity,
        failedAtPhase: phaseBeforeFail || existing.failedAtPhase || null,
      });
      delete patch.error;
    }
  }
}

// Explicit --requeue-transport ??? only when TRANSPORT_REQUEUE_MAX > 0.
// Default policy: fail once ??? Manual Review (refuse auto-rerun).
if (args["requeue-transport"]) {
  if (TRANSPORT_REQUEUE_MAX > 0) {
    softRequeued = true;
    patch.status = "claimed";
    patch.workerId = null;
    patch.lastError = null;

  );
}

export function findJob(data, jobId) {
  return data.jobs.find((j) => j.id === jobId) || null;
}

export function updateJob(data, jobId, patch) {
  const job = findJob(data, jobId);
  if (!job) return null;
  Object.assign(job, patch, { updatedAt: new Date().toISOString() });
  return job;
}

export function touchOrchestrator(notes, pid = process.pid) {
  const data = readJobs();
  data.orchestrator = {
    status: "running",
    pid,
    heartbeat: new Date().toISOString(),
    notes: notes || data.orchestrator?.notes || null,
  };
  return writeJobs(data);
}

export function listDashboardAgents(data = readJobs()) {
  const agents = [];
  const orch = data.orchestrator || {};
  const jobs = Array.isArray(data.jobs) ? data.jobs : [];
  const pending = jobs.filter((j) =>
    ["claimed", "researching", "building", "qa", "ready", "blessing", "merging"].includes(
      j.status,
    ),
  );
  const claimedWaiting = jobs.filter((j) => j.status === "claimed" && !j.workerId);
  const busyWorkers = Object.values(data.workers || {}).filter(
    (w) => w.status === "busy" || w.jobId,
  ).length;

  let orchActivity = orch.notes;
  if (!orchActivity) {
    if (orch.status === "running") {
      orchActivity =
        claimedWaiting.length > 0
          ? `Dispatching ${claimedWaiting.length} claimed job(s) | ${busyWorkers}/4 workers busy`
          : pending.length > 0
            ? `Monitoring ${pending.length} in-flight job(s) | ${busyWorkers}/4 busy`
            : "Idle - waiting to claim next topics";
    } else {
      orchActivity =
        pending.length > 0
          ? `Offline | ${pending.length} job(s) queued (resume automation)`
          : "Offline - start orchestrator to schedule workers";
    }
  }

  agents.push({
    id: "orchestrator",
    role: "Orchestrator",
    kind: "orchestrator",
    pid: orch.pid || null,
    state: orch.status === "running" ? "active" : orch.status || "idle",
    statusLabel: orch.notes || orch.status || "Idle",
    activity: orchActivity,
    attemptsLabel: "1x",
    runningForLabel: null,
    jobId: null,
    runId: data.runId || null,
  });

  for (const w of Object.values(data.workers || {})) {
    const job = w.jobId ? findJob(data, w.jobId) : null;
    const alive = w.pid != null;
    let activity = job?.activity || null;
    if (!activity) {
      if (job) activity = `${job.status}: ${job.slug}`;
      else if (alive && w.status === "busy") activity = "Busy - no job linked yet";
      else if (alive) activity = "Idle - waiting for job assignment";
      else activity = "Slot empty - worker not started";
    }

